import subprocess, time, socket, threading, os, re, sys
def strip(b):
    return re.sub(rb'\x1b\[[0-9;]*m',b'',b).decode(errors='replace')
def start(name,args,env=None):
    f=open(f"/tmp/probe/{name}.log","wb")
    e=os.environ.copy()
    if env: e.update(env)
    p=subprocess.Popen(args, stdout=f, stderr=subprocess.STDOUT, env=e)
    return p,f
procs=[]
try:
    server,_=start("server",["./executable","server"]); procs.append(server)
    time.sleep(0.5)
    # backend echo server
    backend=socket.socket(); backend.setsockopt(socket.SOL_SOCKET,socket.SO_REUSEADDR,1); backend.bind(("127.0.0.1",18080)); backend.listen(5)
    def echo_loop():
        while True:
            try: c,a=backend.accept()
            except: break
            def handle(c):
                c.settimeout(5)
                try:
                    while True:
                        d=c.recv(4096)
                        if not d: break
                        c.sendall(b"ECHO:"+d)
                except Exception as e: print("backend conn err",e,flush=True)
                c.close()
            threading.Thread(target=handle,args=(c,),daemon=True).start()
    threading.Thread(target=echo_loop,daemon=True).start()
    client,_=start("client",["./executable","local","18080","--to","127.0.0.1","--port","18081"]); procs.append(client)
    time.sleep(0.8)
    print("server poll",server.poll(),"client poll",client.poll())
    # external
    for i in range(3):
        ext=socket.create_connection(("127.0.0.1",18081),timeout=2); ext.settimeout(2)
        ext.sendall(f"msg{i}".encode())
        print("ext recv",i, ext.recv(4096))
        ext.close(); time.sleep(0.2)
    # large
    ext=socket.create_connection(("127.0.0.1",18081),timeout=2); ext.settimeout(3)
    big=b"A"*200000
    ext.sendall(big)
    got=b""
    while len(got)<len(big)+5:
        chunk=ext.recv(65536)
        if not chunk: break
        got+=chunk
    print("large ok", len(got), got[:5], got==b"ECHO:"+big)
    ext.close()
    # half close: send then shutdown write, expect echo then EOF?
    ext=socket.create_connection(("127.0.0.1",18081),timeout=2); ext.settimeout(3)
    ext.sendall(b"half"); ext.shutdown(socket.SHUT_WR)
    print("half recv", ext.recv(4096))
    try: print("half recv2", ext.recv(4096))
    except Exception as e: print("half err",e)
    ext.close()
    time.sleep(0.5)
    print("after poll",server.poll(),client.poll())
finally:
    for p in procs:
        if p.poll() is None: p.terminate()
    for p in procs:
        try: p.wait(timeout=2)
        except: p.kill()
for name in ["server","client"]:
    print(f"---{name} log---")
    print(strip(open(f"/tmp/probe/{name}.log","rb").read()))
