import subprocess,time,socket,re,hashlib,hmac,uuid
def strip(s): return re.sub(r'\x1b\[[0-9;]*m','',s)
def run(actions,label,sec=False):
    print("==",label)
    args=["./executable","server"]+(["--secret","mysecret"] if sec else [])
    f=open("/tmp/probe/server.log","wb"); p=subprocess.Popen(args,stdout=f,stderr=subprocess.STDOUT); time.sleep(0.4); t0=time.time()
    s=socket.create_connection(("127.0.0.1",7835),timeout=1); s.settimeout(6)
    try:
        for delay,msg in actions:
            time.sleep(delay)
            if msg:
                if msg=="CORRECT":
                    # need challenge parsed from earlier recv stored in variable? Simplify first action recv externally
                    pass
                print(f"{time.time()-t0:.2f} send",msg); s.sendall(msg)
            try:
                r=s.recv(4096); print(f"{time.time()-t0:.2f} recv",r)
                if b"Challenge" in r:
                    ch=re.search(rb'"Challenge":"([^"]+)"',r).group(1).decode()
                    token=hmac.new(hashlib.sha256(b"mysecret").digest(), uuid.UUID(ch).bytes, hashlib.sha256).hexdigest()
                    print(" -> send correct auth"); s.sendall(f'{{"Authenticate":"{token}"}}\x00'.encode())
            except Exception as e: print(f"{time.time()-t0:.2f} recv err",e)
    except Exception as e: print("err",e)
    finally:
        s.close(); time.sleep(0.3); p.terminate(); p.wait(); f.close()
    print(strip(open("/tmp/probe/server.log").read()))
