use std::collections::HashMap;
use std::env;
use std::fmt;
use std::io::{self, Read, Write};
use std::net::{IpAddr, Shutdown, SocketAddr, TcpListener, TcpStream};
use std::process;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::{mpsc, Arc, Mutex, OnceLock};
use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};

use clap::{Arg, Command};
use serde::{de, Deserialize, Deserializer, Serialize, Serializer};
use sha2::{Digest, Sha256};

const CONTROL_PORT: u16 = 7835;

// ---------- Errors ----------

#[derive(Clone, Debug)]
struct AppError {
    message: String,
    source: Option<String>,
}

impl AppError {
    fn new(message: impl Into<String>) -> Self {
        Self { message: message.into(), source: None }
    }
    fn with_source(message: impl Into<String>, source: impl Into<String>) -> Self {
        Self { message: message.into(), source: Some(source.into()) }
    }
    fn io(err: io::Error) -> Self {
        Self::new(err.to_string())
    }
    fn context(context: String, err: io::Error) -> Self {
        Self::with_source(context, err.to_string())
    }
    fn timeout() -> Self {
        Self::with_source("timed out waiting for initial message", "deadline has elapsed")
    }
    fn is_timeout(&self) -> bool {
        self.message == "timed out waiting for initial message"
    }
}

// ---------- Logging ----------

const LV_ERROR: u8 = 1;
const LV_WARN: u8 = 2;
const LV_INFO: u8 = 3;
const LV_DEBUG: u8 = 4;
const LV_TRACE: u8 = 5;

fn parse_level(text: &str) -> Option<u8> {
    match text.to_ascii_lowercase().as_str() {
        "off" => Some(0),
        "error" => Some(LV_ERROR),
        "warn" | "warning" => Some(LV_WARN),
        "info" => Some(LV_INFO),
        "debug" => Some(LV_DEBUG),
        "trace" => Some(LV_TRACE),
        _ => None,
    }
}

#[derive(Clone, Debug)]
struct Directive {
    target: Option<String>,
    level: u8,
}

struct Logger {
    directives: Vec<Directive>,
    ansi: bool,
}

static LOGGER: OnceLock<Logger> = OnceLock::new();
static LOG_LOCK: Mutex<()> = Mutex::new(());

fn init_logger() {
    let ansi = match env::var("NO_COLOR") {
        Ok(v) => v.is_empty(),
        Err(_) => true,
    };
    let directives = match env::var("RUST_LOG") {
        Err(_) => vec![Directive { target: None, level: LV_INFO }],
        Ok(raw) => {
            let mut dirs: Vec<Directive> = Vec::new();
            for token in raw.split(',') {
                let token = token.trim();
                if token.is_empty() {
                    continue;
                }
                if let Some(level) = parse_level(token) {
                    dirs.push(Directive { target: None, level });
                    continue;
                }
                // Numeric single levels, as accepted by logging filters.
                if token.len() == 1 {
                    if let Some(digit) = token.chars().next().unwrap().to_digit(10) {
                        let lvl = [0, LV_ERROR, LV_WARN, LV_INFO, LV_DEBUG, LV_TRACE]
                            .get(digit as usize)
                            .copied()
                            .unwrap_or(LV_TRACE);
                        dirs.push(Directive { target: None, level: lvl });
                        continue;
                    }
                }
                if let Some(eq) = token.find('=') {
                    let (target, level_text) = token.split_at(eq);
                    let level_text = &level_text[1..];
                    if level_text.is_empty() {
                        dirs.push(Directive {
                            target: Some(target.to_string()),
                            level: LV_TRACE,
                        });
                    } else if let Some(level) = parse_level(level_text) {
                        dirs.push(Directive {
                            target: Some(target.to_string()),
                            level,
                        });
                    } else {
                        // A directive with a non-level filter expression; it does
                        // not match our simple targets in a useful way, but its
                        // presence prevents the default ERROR directive.
                        dirs.push(Directive {
                            target: Some(target.to_string()),
                            level: 0,
                        });
                    }
                } else {
                    dirs.push(Directive {
                        target: Some(token.to_string()),
                        level: LV_TRACE,
                    });
                }
            }
            if dirs.is_empty() {
                dirs.push(Directive { target: None, level: LV_ERROR });
            }
            dirs
        }
    };
    let _ = LOGGER.set(Logger { directives, ansi });
}

fn logger() -> &'static Logger {
    LOGGER.get().expect("logger not initialized")
}

fn level_enabled(level: u8, target: &str) -> bool {
    let log = match LOGGER.get() {
        Some(l) => l,
        None => return level <= LV_INFO,
    };
    let mut best: Option<&Directive> = None;
    let mut best_len: i64 = -1;
    for d in &log.directives {
        if let Some(t) = &d.target {
            if target == t || target.starts_with(t.as_str()) {
                let len = t.len() as i64;
                if len > best_len || (len == best_len && best.map(|b| d.level > b.level).unwrap_or(false)) {
                    best = Some(d);
                    best_len = len;
                }
            }
        }
    }
    if let Some(d) = best {
        return level <= d.level;
    }
    // Global directives.
    let mut result: Option<u8> = None;
    for d in &log.directives {
        if d.target.is_none() {
            result = Some(d.level);
        }
    }
    match result {
        Some(l) => level <= l,
        None => false,
    }
}

#[derive(Clone, Debug)]
struct Span {
    name: String,
    fields: Vec<(String, String)>,
}

impl Span {
    fn new(name: &str, fields: Vec<(String, String)>, span_target: &str) -> Option<Span> {
        if level_enabled(LV_INFO, span_target) {
            Some(Span { name: name.to_string(), fields })
        } else {
            None
        }
    }
}

fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719_468;
    let era = if z >= 0 { z } else { z - 146_096 } / 146_097;
    let doe = (z - era * 146_097) as u64;
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
    let y = yoe as i64 + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    (if m <= 2 { y + 1 } else { y }, m, d)
}

fn timestamp_now() -> String {
    let dur = SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default();
    let secs = dur.as_secs() as i64;
    let micros = dur.subsec_micros();
    let days = secs.div_euclid(86_400);
    let secs_of_day = secs.rem_euclid(86_400);
    let (y, m, d) = civil_from_days(days);
    let hh = secs_of_day / 3600;
    let mm = (secs_of_day % 3600) / 60;
    let ss = secs_of_day % 60;
    format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}.{:06}Z", y, m, d, hh, mm, ss, micros)
}

fn log_event(level: u8, target: &str, span: Option<&Span>, message: &str, fields: &[(&str, String)]) {
    if !level_enabled(level, target) {
        return;
    }
    let (level_text, color) = match level {
        LV_ERROR => ("ERROR", "31"),
        LV_WARN => ("WARN", "33"),
        LV_INFO => ("INFO", "32"),
        LV_DEBUG => ("DEBUG", "34"),
        _ => ("TRACE", "35"),
    };
    let ts = timestamp_now();
    let ansi = LOGGER.get().map(|l| l.ansi).unwrap_or(true);
    let mut line = String::new();
    if ansi {
        line.push_str(&format!("\x1b[2m{}\x1b[0m \x1b[{}m{:>5}\x1b[0m ", ts, color, level_text));
        if let Some(sp) = span {
            line.push_str(&format!("\x1b[1m{}\x1b[0m\x1b[1m{{\x1b[0m", sp.name));
            for (i, (k, v)) in sp.fields.iter().enumerate() {
                if i > 0 {
                    line.push(' ');
                }
                line.push_str(&format!("\x1b[3m{}\x1b[0m\x1b[2m=\x1b[0m{}", k, v));
            }
            line.push_str("\x1b[1m}\x1b[0m\x1b[2m:\x1b[0m ");
        }
        line.push_str(&format!("\x1b[2m{}\x1b[0m\x1b[2m:\x1b[0m {}", target, message));
        for (k, v) in fields {
            line.push_str(&format!(" \x1b[3m{}\x1b[0m\x1b[2m=\x1b[0m{}", k, v));
        }
    } else {
        line.push_str(&format!("{} {:>5} ", ts, level_text));
        if let Some(sp) = span {
            line.push_str(&format!("{}{{", sp.name));
            for (i, (k, v)) in sp.fields.iter().enumerate() {
                if i > 0 {
                    line.push(' ');
                }
                line.push_str(&format!("{}={}", k, v));
            }
            line.push_str("}: ");
        }
        line.push_str(&format!("{}: {}", target, message));
        for (k, v) in fields {
            line.push_str(&format!(" {}={}", k, v));
        }
    }
    line.push('\n');
    let _guard = LOG_LOCK.lock().unwrap_or_else(|p| p.into_inner());
    let stdout = io::stdout();
    let mut handle = stdout.lock();
    let _ = handle.write_all(line.as_bytes());
    let _ = handle.flush();
}

fn log_info(target: &str, span: Option<&Span>, message: &str, fields: &[(&str, String)]) {
    log_event(LV_INFO, target, span, message, fields);
}
fn log_warn(target: &str, span: Option<&Span>, message: &str, fields: &[(&str, String)]) {
    log_event(LV_WARN, target, span, message, fields);
}
fn log_error(target: &str, span: Option<&Span>, message: &str, fields: &[(&str, String)]) {
    log_event(LV_ERROR, target, span, message, fields);
}
fn log_trace_shared(span: Option<&Span>, message: &str) {
    log_event(LV_TRACE, "bore_cli::shared", span, message, &[]);
}

// ---------- UUID ----------

#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
struct UuidVal([u8; 16]);

static RAND_COUNTER: AtomicU64 = AtomicU64::new(0);

fn fill_random(buf: &mut [u8]) {
    if let Ok(mut file) = std::fs::File::open("/dev/urandom") {
        if file.read_exact(buf).is_ok() {
            return;
        }
    }
    // Fallback only used when /dev/urandom is unavailable.
    let mut seed = Vec::new();
    let now = SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default();
    seed.extend_from_slice(&now.as_nanos().to_le_bytes());
    seed.extend_from_slice(&process::id().to_le_bytes());
    seed.extend_from_slice(&RAND_COUNTER.fetch_add(1, Ordering::SeqCst).to_le_bytes());
    let digest = Sha256::digest(&seed);
    for (i, b) in buf.iter_mut().enumerate() {
        *b = digest[i % digest.len()];
    }
}

impl UuidVal {
    fn new_v4() -> Self {
        let mut b = [0u8; 16];
        fill_random(&mut b);
        b[6] = (b[6] & 0x0f) | 0x40;
        b[8] = (b[8] & 0x3f) | 0x80;
        Self(b)
    }

    fn parse(input: &str) -> Result<Self, String> {
        let (inner, offset, forced_hyphenated): (&str, usize, bool) =
            if let Some(rest) = input.strip_prefix("urn:uuid:") {
                (rest, 9, true)
            } else if input.len() >= 2 && input.starts_with('{') && input.ends_with('}') {
                (&input[1..input.len() - 1], 1, true)
            } else {
                (input, 0, false)
            };
        for (rel, ch) in inner.char_indices() {
            if !(ch.is_ascii_hexdigit() || ch == '-') {
                return Err(format!(
                    "invalid character: expected an optional prefix of `urn:uuid:` followed by [0-9a-fA-F-], found `{}` at {}",
                    ch,
                    offset + rel + 1
                ));
            }
        }
        let mut bytes = [0u8; 16];
        if forced_hyphenated || inner.contains('-') {
            let groups: Vec<&str> = inner.split('-').collect();
            if groups.len() != 5 {
                return Err(format!(
                    "invalid group count: expected 5, found {}",
                    groups.len()
                ));
            }
            let expected = [8usize, 4, 4, 4, 12];
            for (idx, group) in groups.iter().enumerate() {
                if group.chars().count() != expected[idx] {
                    return Err(format!(
                        "invalid group length in group {}: expected {}, found {}",
                        idx,
                        expected[idx],
                        group.chars().count()
                    ));
                }
            }
            let joined: String = groups.concat();
            fill_bytes_from_hex(&joined, &mut bytes);
        } else {
            if inner.chars().count() != 32 {
                return Err(format!(
                    "invalid length: expected length 32 for simple format, found {}",
                    inner.chars().count()
                ));
            }
            fill_bytes_from_hex(inner, &mut bytes);
        }
        Ok(Self(bytes))
    }
}

fn fill_bytes_from_hex(hex: &str, out: &mut [u8; 16]) {
    let bytes = hex.as_bytes();
    for i in 0..16 {
        if 2 * i + 1 < bytes.len() {
            let hi = (bytes[2 * i] as char).to_digit(16).unwrap_or(0) as u8;
            let lo = (bytes[2 * i + 1] as char).to_digit(16).unwrap_or(0) as u8;
            out[i] = (hi << 4) | lo;
        }
    }
}

impl fmt::Display for UuidVal {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let b = &self.0;
        write!(
            f,
            "{:02x}{:02x}{:02x}{:02x}-{:02x}{:02x}-{:02x}{:02x}-{:02x}{:02x}-{:02x}{:02x}{:02x}{:02x}{:02x}{:02x}",
            b[0], b[1], b[2], b[3], b[4], b[5], b[6], b[7], b[8], b[9], b[10], b[11], b[12], b[13], b[14], b[15]
        )
    }
}

impl Serialize for UuidVal {
    fn serialize<S: Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        serializer.serialize_str(&self.to_string())
    }
}

impl<'de> Deserialize<'de> for UuidVal {
    fn deserialize<D: Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        struct Visitor;
        impl<'de> de::Visitor<'de> for Visitor {
            type Value = UuidVal;
            fn expecting(&self, formatter: &mut fmt::Formatter) -> fmt::Result {
                formatter.write_str("a UUID string")
            }
            fn visit_str<E: de::Error>(self, value: &str) -> Result<UuidVal, E> {
                UuidVal::parse(value)
                    .map_err(|e| E::custom(format!("UUID parsing failed: {}", e)))
            }
            fn visit_string<E: de::Error>(self, value: String) -> Result<UuidVal, E> {
                self.visit_str(&value)
            }
        }
        deserializer.deserialize_string(Visitor)
    }
}

// ---------- Messages ----------

#[derive(Serialize, Deserialize, Debug, Clone)]
enum ClientMessage {
    Authenticate(String),
    Hello(u16),
    Accept(UuidVal),
}

#[derive(Serialize, Deserialize, Debug, Clone)]
enum ServerMessage {
