// ---------- Framed JSON stream ----------

struct Framed {
    stream: TcpStream,
    buffer: Vec<u8>,
    at_eof: bool,
    deadline: Option<Instant>,
}

impl Framed {
    fn new(stream: TcpStream) -> Self {
        Self { stream, buffer: Vec::new(), at_eof: false, deadline: None }
    }

    fn set_deadline(&mut self, duration: Duration) {
        self.deadline = Some(Instant::now() + duration);
    }

    fn clear_deadline(&mut self) {
        self.deadline = None;
        let _ = self.stream.set_read_timeout(None);
    }

    fn read_frame(&mut self) -> Result<Option<Vec<u8>>, AppError> {
        if self.at_eof {
            return Ok(None);
        }
        loop {
            if let Some(deadline) = self.deadline {
                let now = Instant::now();
                if now >= deadline {
                    return Err(AppError::timeout());
                }
                let _ = self.stream.set_read_timeout(Some(deadline - now));
            }
            let mut byte = [0u8; 1];
            match self.stream.read(&mut byte) {
                Ok(0) => {
                    self.at_eof = true;
                    if self.buffer.is_empty() {
                        return Ok(None);
                    }
                    return Ok(Some(std::mem::take(&mut self.buffer)));
                }
                Ok(_) => {
                    let b = byte[0];
                    if b == 0 {
                        return Ok(Some(std::mem::take(&mut self.buffer)));
                    }
                    self.buffer.push(b);
                    if self.buffer.len() > 256 {
                        return Err(AppError::with_source(
                            "frame error, invalid byte length",
                            "max chunk length exceeded",
                        ));
                    }
                }
                Err(e) if e.kind() == io::ErrorKind::Interrupted => continue,
                Err(e) => {
                    if self.deadline.is_some()
                        && (e.kind() == io::ErrorKind::WouldBlock || e.kind() == io::ErrorKind::TimedOut)
                    {
                        return Err(AppError::timeout());
                    }
                    return Err(AppError::with_source(
                        "frame error, invalid byte length",
                        e.to_string(),
                    ));
                }
            }
        }
    }

    fn recv_msg<T>(&mut self, span: Option<&Span>) -> Result<Option<T>, AppError>
    where
        T: for<'de> Deserialize<'de>,
    {
        log_trace_shared(span, "waiting to receive json message");
        let frame = match self.read_frame()? {
            None => return Ok(None),
            Some(f) => f,
        };
        match serde_json::from_slice::<Option<T>>(&frame) {
            Ok(v) => Ok(v),
            Err(e) => Err(AppError::with_source("unable to parse message", e.to_string())),
        }
    }

    fn send_msg<T: Serialize>(&mut self, msg: &T, span: Option<&Span>) -> Result<(), AppError> {
        log_trace_shared(span, "sending json message");
        let mut bytes = serde_json::to_vec(msg).unwrap_or_default();
        bytes.push(0);
        self.stream.write_all(&bytes).map_err(AppError::io)
    }

    fn into_stream(self) -> TcpStream {
        self.stream
    }
}

// ---------- Auth helpers ----------

fn sha256(data: &[u8]) -> [u8; 32] {
    let digest = Sha256::digest(data);
    let mut out = [0u8; 32];
    out.copy_from_slice(&digest);
    out
}

fn hmac_sha256(key: &[u8], message: &[u8]) -> [u8; 32] {
    let mut key_block = [0u8; 64];
    if key.len() > 64 {
        let hashed = sha256(key);
        key_block[..32].copy_from_slice(&hashed);
    } else {
        key_block[..key.len()].copy_from_slice(key);
    }
    let mut ipad = [0x36u8; 64];
    let mut opad = [0x5cu8; 64];
    for i in 0..64 {
        ipad[i] ^= key_block[i];
        opad[i] ^= key_block[i];
    }
    let mut inner = Vec::with_capacity(64 + message.len());
    inner.extend_from_slice(&ipad);
    inner.extend_from_slice(message);
    let inner_hash = sha256(&inner);
    let mut outer = Vec::with_capacity(64 + 32);
    outer.extend_from_slice(&opad);
    outer.extend_from_slice(&inner_hash);
    sha256(&outer)
}

fn authenticate_token(secret: &str, challenge: &UuidVal) -> [u8; 32] {
    let key = sha256(secret.as_bytes());
    hmac_sha256(&key, &challenge.0)
}

fn hex_encode(bytes: &[u8]) -> String {
    let mut out = String::with_capacity(bytes.len() * 2);
    for b in bytes {
        out.push_str(&format!("{:02x}", b));
    }
    out
}

fn hex_decode(text: &str) -> Option<Vec<u8>> {
    if text.len() % 2 != 0 {
        return None;
    }
    let chars: Vec<char> = text.chars().collect();
    if chars.len() * 1 != text.len() {
        // Non-ASCII input cannot be hex.
        if !text.is_ascii() {
            return None;
        }
    }
    let mut out = Vec::with_capacity(text.len() / 2);
    let bytes = text.as_bytes();
    for i in (0..bytes.len()).step_by(2) {
        let hi = (bytes[i] as char).to_digit(16)?;
        let lo = (bytes[i + 1] as char).to_digit(16)?;
        out.push(((hi << 4) | lo) as u8);
    }
    Some(out)
}

fn verify_token(secret: &str, challenge: &UuidVal, token: &str) -> bool {
    let expected = authenticate_token(secret, challenge);
    match hex_decode(token) {
        Some(decoded) => decoded.len() == expected.len() && decoded.as_slice() == expected.as_slice(),
        None => false,
    }
}

// ---------- Proxy copy ----------

fn copy_one(mut src: TcpStream, mut dst: TcpStream) -> Result<(), io::Error> {
    let mut buf = [0u8; 16384];
    loop {
        match src.read(&mut buf) {
            Ok(0) => {
                let _ = dst.shutdown(Shutdown::Write);
                return Ok(());
            }
            Ok(n) => {
                if let Err(e) = dst.write_all(&buf[..n]) {
                    let _ = src.shutdown(Shutdown::Both);
                    let _ = dst.shutdown(Shutdown::Both);
                    return Err(e);
                }
            }
            Err(e) if e.kind() == io::ErrorKind::Interrupted => continue,
            Err(e) => {
                let _ = src.shutdown(Shutdown::Both);
                let _ = dst.shutdown(Shutdown::Both);
                return Err(e);
            }
        }
    }
}

fn copy_bidirectional(a: TcpStream, b: TcpStream) -> Result<(), AppError> {
    let (tx, rx) = mpsc::channel::<Result<(), io::Error>>();
    let a_read = match a.try_clone() {
        Ok(s) => s,
        Err(e) => return Err(AppError::io(e)),
    };
    let b_write = match b.try_clone() {
        Ok(s) => s,
        Err(e) => return Err(AppError::io(e)),
    };
    let tx2 = tx.clone();
    std::thread::spawn(move || {
        let _ = tx2.send(copy_one(a_read, b_write));
    });
    let b_read = match b.try_clone() {
        Ok(s) => s,
        Err(e) => return Err(AppError::io(e)),
    };
    let a_write = match a.try_clone() {
        Ok(s) => s,
        Err(e) => return Err(AppError::io(e)),
    };
    std::thread::spawn(move || {
        let _ = tx.send(copy_one(b_read, a_write));
    });
    let first = match rx.recv() {
        Ok(r) => r,
        Err(_) => return Ok(()),
    };
    if let Err(e) = first {
        let _ = a.shutdown(Shutdown::Both);
        let _ = b.shutdown(Shutdown::Both);
        let _ = rx.recv();
        return Err(AppError::io(e));
    }
    match rx.recv() {
        Ok(Ok(())) => Ok(()),
        Ok(Err(e)) => Err(AppError::io(e)),
        Err(_) => Ok(()),
    }
}

// ---------- Client ----------

#[derive(Clone)]
struct ClientConfig {
    local_port: u16,
    local_host: String,
    to: String,
    port: u16,
    secret: Option<String>,
}

fn connect_remote(cfg: &ClientConfig) -> Result<TcpStream, AppError> {
    TcpStream::connect((cfg.to.as_str(), CONTROL_PORT)).map_err(|e| {
        AppError::context(format!("could not connect to {}:{}", cfg.to, CONTROL_PORT), e)
    })
}

fn client_authenticate(
    framed: &mut Framed,
    secret: &str,
    span: Option<&Span>,
) -> Result<(), AppError> {
    let message: Option<ServerMessage> = framed.recv_msg(span)?;
    match message {
        Some(ServerMessage::Challenge(challenge)) => {
            let token = authenticate_token(secret, &challenge);
            framed.send_msg(&ClientMessage::Authenticate(hex_encode(&token)), span)
        }
        _ => Err(AppError::new(
            "expected authentication challenge, but no secret was required",
        )),
    }
}

fn client_proxy(cfg: ClientConfig, id: UuidVal) -> Result<(), AppError> {
    let stream = connect_remote(&cfg)?;
    let mut framed = Framed::new(stream);
    framed.set_deadline(Duration::from_secs(3));
    if let Some(secret) = &cfg.secret {
        client_authenticate(&mut framed, secret, None)?;
    }
    framed.send_msg(&ClientMessage::Accept(id), None)?;
    framed.clear_deadline();
    let local = TcpStream::connect((cfg.local_host.as_str(), cfg.local_port)).map_err(|e| {
        AppError::context(
            format!("could not connect to {}:{}", cfg.local_host, cfg.local_port),
            e,
        )
    })?;
    copy_bidirectional(framed.into_stream(), local)
}

fn run_client(cfg: ClientConfig) -> Result<(), AppError> {
    let stream = connect_remote(&cfg)?;
    let mut framed = Framed::new(stream);
    framed.set_deadline(Duration::from_secs(3));

    if let Some(secret) = &cfg.secret {
        client_authenticate(&mut framed, secret, None)?;
    }
    framed.send_msg(&ClientMessage::Hello(cfg.port), None)?;

    let remote_port: u16 = {
        let message: Option<ServerMessage> = framed.recv_msg(None)?;
        match message {
            Some(ServerMessage::Hello(port)) => port,
            Some(ServerMessage::Error(text)) => {
                return Err(AppError::new(format!("server error: {}", text)))
            }
            Some(ServerMessage::Challenge(_)) => {
                return Err(AppError::new(
                    "server requires authentication, but no client secret was provided",
                ))
            }
            Some(_) => return Err(AppError::new("unexpected initial non-hello message")),
            None => return Err(AppError::new("unexpected EOF")),
        }
    };
    framed.clear_deadline();

    log_info(
        "bore_cli::client",
        None,
        "connected to server",
        &[("remote_port", remote_port.to_string())],
    );
    log_info(
        "bore_cli::client",
        None,
        &format!("listening at {}:{}", cfg.to, remote_port),
        &[],
    );

    loop {
        let message: Option<ServerMessage> = framed.recv_msg(None)?;
        let message = match message {
            None => break,
            Some(m) => m,
        };
        match message {
            ServerMessage::Heartbeat => {}
            ServerMessage::Connection(id) => {
                let span = Span::new("proxy", vec![("id".to_string(), id.to_string())], "bore_cli::client");
                log_info("bore_cli::client", span.as_ref(), "new connection", &[]);
                let cfg_clone = cfg.clone();
                std::thread::spawn(move || {
                    let span2 = Span::new(
                        "proxy",
                        vec![("id".to_string(), id.to_string())],
                        "bore_cli::client",
                    );
                    match client_proxy(cfg_clone, id) {
                        Ok(()) => log_info(
                            "bore_cli::client",
                            span2.as_ref(),
                            "connection exited",
                            &[],
                        ),
                        Err(e) => log_warn(
                            "bore_cli::client",
                            span2.as_ref(),
                            "connection exited with error",
                            &[("err", e.message.clone())],
                        ),
                    }
                });
            }
            ServerMessage::Hello(_) => {
                log_warn("bore_cli::client", None, "unexpected hello", &[])
            }
            ServerMessage::Challenge(_) => {
                log_warn("bore_cli::client", None, "unexpected challenge", &[])
            }
            ServerMessage::Error(text) => {
                log_error("bore_cli::client", None, "server error", &[("err", text)])
            }
        }
    }
    Ok(())
}

// ---------- Server ----------

#[derive(Clone)]
struct ServerConfig {
    min_port: u16,
    max_port: u16,
    secret: Option<String>,
    bind_addr: IpAddr,
    bind_tunnels: IpAddr,
}

type Connections = Arc<Mutex<HashMap<UuidVal, TcpStream>>>;

enum HandshakeOutcome {
    Proceed,
    Done,
    Err(AppError),
}

fn server_handshake(
    framed: &mut Framed,
    secret: &str,
    span: Option<&Span>,
) -> HandshakeOutcome {
    let challenge = UuidVal::new_v4();
    if let Err(e) = framed.send_msg(&ServerMessage::Challenge(challenge), span) {
        // Treat a failure to send the challenge like other handshake errors:
        // report it, then try to inform the peer.
        log_warn(
            "bore_cli::server",
            span,
            "server handshake failed",
            &[("err", e.message.clone())],
        );
        if let Err(send_err) = framed.send_msg(&ServerMessage::Error(e.message.clone()), span) {
            return HandshakeOutcome::Err(send_err);
        }
        return HandshakeOutcome::Done;
    }

    let received: Result<Option<ClientMessage>, AppError> = framed.recv_msg(span);
    let error_message: String = match received {
        Err(e) => {
            if e.is_timeout() {
                return HandshakeOutcome::Err(e);
            }
            e.message.clone()
        }
        Ok(Some(ClientMessage::Authenticate(token))) => {
            if verify_token(secret, &challenge, &token) {
                return HandshakeOutcome::Proceed;
            }
            "invalid secret".to_string()
        }
        Ok(_) => "server requires secret, but no secret was provided".to_string(),
    };

    log_warn(
        "bore_cli::server",
        span,
        "server handshake failed",
        &[("err", error_message.clone())],
    );
    if let Err(send_err) = framed.send_msg(&ServerMessage::Error(error_message), span) {
        return HandshakeOutcome::Err(send_err);
    }
    HandshakeOutcome::Done
}

fn random_port(min_port: u16, max_port: u16) -> u16 {
    let span = (max_port as u64 - min_port as u64) + 1;
    if span <= 1 {
        return min_port;
    }
    let mut bytes = [0u8; 8];
    fill_random(&mut bytes);
    let value = u64::from_le_bytes(bytes);
    min_port + ((value % span) as u16)
}

fn server_connection_inner(
    mut framed: Framed,
    cfg: Arc<ServerConfig>,
    connections: Connections,
    span: Option<&Span>,
) -> Result<(), AppError> {
    framed.set_deadline(Duration::from_secs(3));

    if let Some(secret) = &cfg.secret {
        match server_handshake(&mut framed, secret, span) {
            HandshakeOutcome::Proceed => {}
            HandshakeOutcome::Done => return Ok(()),
            HandshakeOutcome::Err(e) => return Err(e),
        }
    }

    let first: Option<ClientMessage> = framed.recv_msg(span)?;
    let first = match first {
        None => return Ok(()),
        Some(m) => m,
    };

    match first {
        ClientMessage::Authenticate(_) => {
            log_warn("bore_cli::server", span, "unexpected authenticate", &[]);
            Ok(())
        }
        ClientMessage::Accept(id) => {
            framed.clear_deadline();
            log_info(
                "bore_cli::server",
                span,
                "forwarding connection",
                &[("id", id.to_string())],
            );
            let external = {
                let mut map = connections.lock().unwrap_or_else(|p| p.into_inner());
                map.remove(&id)
            };
            match external {
                Some(external_stream) => {
                    copy_bidirectional(framed.into_stream(), external_stream)
                }
                None => {
                    log_warn(
                        "bore_cli::server",
                        span,
                        "missing connection",
                        &[("id", id.to_string())],
                    );
                    Ok(())
                }
            }
        }
        ClientMessage::Hello(requested) => {
            framed.clear_deadline();
            if requested != 0 && !(cfg.min_port <= requested && requested <= cfg.max_port) {
                framed.send_msg(
                    &ServerMessage::Error(
                        "client port number not in allowed range".to_string(),
                    ),
                    span,
                )?;
                return Ok(());
            }

            let (listener, actual_port): (TcpListener, u16) = if requested != 0 {
                match TcpListener::bind((cfg.bind_tunnels, requested)) {
                    Ok(listener) => {
                        let port = listener.local_addr().map(|a| a.port()).unwrap_or(requested);
                        (listener, port)
                    }
                    Err(e) if e.kind() == io::ErrorKind::AddrInUse => {
                        framed.send_msg(
                            &ServerMessage::Error("port already in use".to_string()),
                            span,
                        )?;
                        return Ok(());
                    }
                    Err(_) => {
                        framed.send_msg(
                            &ServerMessage::Error("failed to bind to port".to_string()),
                            span,
                        )?;
                        return Ok(());
                    }
                }
            } else {
                let mut found: Option<(TcpListener, u16)> = None;
                for _ in 0..200 {
                    let candidate = random_port(cfg.min_port, cfg.max_port);
                    if let Ok(listener) = TcpListener::bind((cfg.bind_tunnels, candidate)) {
                        let port = listener.local_addr().map(|a| a.port()).unwrap_or(candidate);
                        found = Some((listener, port));
                        break;
                    }
                }
                match found {
                    Some(v) => v,
                    None => {
                        framed.send_msg(
                            &ServerMessage::Error(
                                "failed to find an available port".to_string(),
                            ),
                            span,
                        )?;
                        return Ok(());
                    }
                }
            };

            log_info(
                "bore_cli::server",
                span,
                "new client",
                &[
                    ("host", cfg.bind_tunnels.to_string()),
                    ("port", actual_port.to_string()),
                ],
            );
            framed.send_msg(&ServerMessage::Hello(actual_port), span)?;

            if let Err(e) = listener.set_nonblocking(true) {
                return Err(AppError::io(e));
            }

            let mut next_heartbeat = Instant::now();
            loop {
                if Instant::now() >= next_heartbeat {
                    if framed.send_msg(&ServerMessage::Heartbeat, span).is_err() {
                        break;
                    }
                    let scheduled = next_heartbeat + Duration::from_millis(500);
                    let now = Instant::now();
                    next_heartbeat = if scheduled > now {
                        scheduled
                    } else {
                        now + Duration::from_millis(500)
                    };
                }
                match listener.accept() {
                    Ok((external, addr)) => {
                        let _ = external.set_nonblocking(false);
                        log_info(
                            "bore_cli::server",
                            span,
                            "new connection",
                            &[
                                ("addr", addr.to_string()),
                                ("port", actual_port.to_string()),
                            ],
                        );
                        let id = UuidVal::new_v4();
                        {
                            let mut map =
                                connections.lock().unwrap_or_else(|p| p.into_inner());
                            map.insert(id, external);
                        }
                        if framed.send_msg(&ServerMessage::Connection(id), span).is_err() {
                            break;
                        }
                    }
                    Err(e) if e.kind() == io::ErrorKind::WouldBlock => {
                        std::thread::sleep(Duration::from_millis(5));
                    }
                    Err(_) => {
                        std::thread::sleep(Duration::from_millis(5));
                    }
                }
            }
            Ok(())
        }
    }
}

fn handle_server_connection(
    stream: TcpStream,
    peer: SocketAddr,
    cfg: Arc<ServerConfig>,
    connections: Connections,
) {
    let span = Span::new(
        "control",
        vec![("addr".to_string(), peer.to_string())],
        "bore_cli::server",
    );
    log_info("bore_cli::server", span.as_ref(), "incoming connection", &[]);
    let framed = Framed::new(stream);
    match server_connection_inner(framed, cfg, connections, span.as_ref()) {
        Ok(()) => log_info("bore_cli::server", span.as_ref(), "connection exited", &[]),
        Err(e) => log_warn(
            "bore_cli::server",
            span.as_ref(),
            "connection exited with error",
            &[("err", e.message.clone())],
        ),
    }
}

fn run_server(cfg: ServerConfig) -> Result<(), AppError> {
    let cfg = Arc::new(cfg);
    let listener = TcpListener::bind((cfg.bind_addr, CONTROL_PORT)).map_err(AppError::io)?;
    log_info(
        "bore_cli::server",
        None,
        "server listening",
        &[("addr", cfg.bind_addr.to_string())],
    );
    let connections: Connections = Arc::new(Mutex::new(HashMap::new()));
    loop {
        match listener.accept() {
            Ok((stream, peer)) => {
                let cfg_clone = cfg.clone();
                let conns_clone = connections.clone();
                std::thread::spawn(move || {
                    handle_server_connection(stream, peer, cfg_clone, conns_clone);
                });
            }
            Err(_) => {
                std::thread::sleep(Duration::from_millis(1));
            }
        }
    }
}

// ---------- CLI ----------

fn build_cli() -> Command {
    Command::new("bore-cli")
        .version("0.6.0")
        .about("A modern, simple TCP tunnel in Rust that exposes local ports to a remote server, bypassing standard NAT connection firewalls.")
        .subcommand_required(true)
        .arg_required_else_help(true)
        .subcommand(
            Command::new("local")
                .about("Starts a local proxy to the remote server")
                .arg(
                    Arg::new("local_port")
                        .value_name("LOCAL_PORT")
                        .help("The local port to expose")
                        .env("BORE_LOCAL_PORT")
                        .required(true)
                        .value_parser(clap::value_parser!(u16))
                        .index(1),
                )
                .arg(
                    Arg::new("host")
                        .value_name("HOST")
                        .short('l')
                        .long("local-host")
                        .help("The local host to expose")
                        .default_value("localhost"),
                )
                .arg(
                    Arg::new("to")
                        .value_name("TO")
                        .short('t')
                        .long("to")
                        .help("Address of the remote server to expose local ports to")
                        .env("BORE_SERVER")
                        .required(true),
                )
                .arg(
                    Arg::new("port")
                        .value_name("PORT")
                        .short('p')
                        .long("port")
                        .help("Optional port on the remote server to select")
                        .default_value("0")
                        .value_parser(clap::value_parser!(u16)),
                )
                .arg(
                    Arg::new("secret")
                        .value_name("SECRET")
                        .short('s')
                        .long("secret")
                        .help("Optional secret for authentication")
                        .env("BORE_SECRET")
                        .hide_env_values(true),
                ),
        )
        .subcommand(
            Command::new("server")
                .about("Runs the remote proxy server")
                .arg(
                    Arg::new("min_port")
                        .value_name("MIN_PORT")
                        .long("min-port")
                        .help("Minimum accepted TCP port number")
                        .env("BORE_MIN_PORT")
                        .default_value("1024")
                        .value_parser(clap::value_parser!(u16)),
                )
                .arg(
                    Arg::new("max_port")
                        .value_name("MAX_PORT")
                        .long("max-port")
                        .help("Maximum accepted TCP port number")
                        .env("BORE_MAX_PORT")
                        .default_value("65535")
                        .value_parser(clap::value_parser!(u16)),
                )
                .arg(
                    Arg::new("secret")
                        .value_name("SECRET")
                        .short('s')
                        .long("secret")
                        .help("Optional secret for authentication")
                        .env("BORE_SECRET")
                        .hide_env_values(true),
                )
                .arg(
                    Arg::new("bind_addr")
                        .value_name("BIND_ADDR")
                        .long("bind-addr")
                        .help("IP address to bind to, clients must reach this")
                        .default_value("0.0.0.0")
                        .value_parser(clap::value_parser!(std::net::IpAddr)),
                )
                .arg(
                    Arg::new("bind_tunnels")
                        .value_name("BIND_TUNNELS")
                        .long("bind-tunnels")
                        .help("IP address where tunnels will listen on, defaults to --bind-addr")
                        .value_parser(clap::value_parser!(std::net::IpAddr)),
                ),
        )
}

fn print_error_and_exit(err: AppError) -> ! {
    eprintln!("Error: {}", err.message);
    if let Some(source) = &err.source {
        eprintln!("\nCaused by:");
        eprintln!("    {}", source);
    }
    process::exit(1);
}

fn main() {
    let matches = build_cli().get_matches();
    match matches.subcommand() {
        Some(("local", sub)) => {
            let cfg = ClientConfig {
                local_port: *sub.get_one::<u16>("local_port").unwrap_or(&0),
                local_host: sub
                    .get_one::<String>("host")
                    .cloned()
                    .unwrap_or_else(|| "localhost".to_string()),
                to: sub.get_one::<String>("to").cloned().unwrap_or_default(),
                port: *sub.get_one::<u16>("port").unwrap_or(&0),
                secret: sub.get_one::<String>("secret").cloned(),
            };
            init_logger();
            match run_client(cfg) {
                Ok(()) => process::exit(0),
                Err(e) => print_error_and_exit(e),
            }
        }
        Some(("server", sub)) => {
            let min_port = *sub.get_one::<u16>("min_port").unwrap_or(&1024);
            let max_port = *sub.get_one::<u16>("max_port").unwrap_or(&65535);
            if min_port > max_port {
                build_cli()
                    .error(clap::error::ErrorKind::ValueValidation, "port range is empty")
                    .exit();
            }
            let bind_addr = *sub
                .get_one::<IpAddr>("bind_addr")
                .unwrap_or(&IpAddr::from([0, 0, 0, 0]));
            let cfg = ServerConfig {
                min_port,
                max_port,
                secret: sub.get_one::<String>("secret").cloned(),
                bind_addr,
                bind_tunnels: sub
                    .get_one::<IpAddr>("bind_tunnels")
                    .copied()
                    .unwrap_or(bind_addr),
            };
            init_logger();
            match run_server(cfg) {
                Ok(()) => process::exit(0),
                Err(e) => print_error_and_exit(e),
            }
        }
        _ => {
            // Clap's required-subcommand handling normally deals with this.
            process::exit(2);
        }
    }
}
