const CONTROL_PORT: u16 = 7835;

// ---------- Errors ----------

#[derive(Clone, Debug)]
struct AppError {
    message: String,
    source: Option<String>,
}

impl AppError {
    fn new(message: impl Into<String>) -> Self {
        Self { message: message.into(), source: None }
    }
    fn with_source(message: impl Into<String>, source: impl Into<String>) -> Self {
