// ---------- Logging ----------

const LV_ERROR: u8 = 1;
const LV_WARN: u8 = 2;
const LV_INFO: u8 = 3;
const LV_DEBUG: u8 = 4;
const LV_TRACE: u8 = 5;

fn parse_level(text: &str) -> Option<u8> {
    match text.to_ascii_lowercase().as_str() {
        "off" => Some(0),
        "error" => Some(LV_ERROR),
        "warn" | "warning" => Some(LV_WARN),
        "info" => Some(LV_INFO),
        "debug" => Some(LV_DEBUG),
        "trace" => Some(LV_TRACE),
        _ => None,
    }
}

#[derive(Clone, Debug)]
struct Directive {
    target: Option<String>,
    level: u8,
}

struct Logger {
    directives: Vec<Directive>,
    ansi: bool,
}

static LOGGER: OnceLock<Logger> = OnceLock::new();
static LOG_LOCK: Mutex<()> = Mutex::new(());

fn init_logger() {
    let ansi = match env::var("NO_COLOR") {
        Ok(v) => v.is_empty(),
        Err(_) => true,
    };
    let directives = match env::var("RUST_LOG") {
        Err(_) => vec![Directive { target: None, level: LV_INFO }],
        Ok(raw) => {
            let mut dirs: Vec<Directive> = Vec::new();
            for token in raw.split(',') {
                let token = token.trim();
                if token.is_empty() {
                    continue;
                }
                if let Some(level) = parse_level(token) {
                    dirs.push(Directive { target: None, level });
                    continue;
                }
                // Numeric single levels, as accepted by logging filters.
                if token.len() == 1 {
                    if let Some(digit) = token.chars().next().unwrap().to_digit(10) {
                        let lvl = [0, LV_ERROR, LV_WARN, LV_INFO, LV_DEBUG, LV_TRACE]
                            .get(digit as usize)
                            .copied()
                            .unwrap_or(LV_TRACE);
                        dirs.push(Directive { target: None, level: lvl });
                        continue;
                    }
                }
                if let Some(eq) = token.find('=') {
                    let (target, level_text) = token.split_at(eq);
                    let level_text = &level_text[1..];
                    if level_text.is_empty() {
                        dirs.push(Directive {
                            target: Some(target.to_string()),
                            level: LV_TRACE,
                        });
                    } else if let Some(level) = parse_level(level_text) {
                        dirs.push(Directive {
                            target: Some(target.to_string()),
                            level,
                        });
                    } else {
                        // A directive with a non-level filter expression; it does
                        // not match our simple targets in a useful way, but its
                        // presence prevents the default ERROR directive.
                        dirs.push(Directive {
                            target: Some(target.to_string()),
                            level: 0,
                        });
                    }
                } else {
                    dirs.push(Directive {
                        target: Some(token.to_string()),
                        level: LV_TRACE,
                    });
                }
            }
            if dirs.is_empty() {
                dirs.push(Directive { target: None, level: LV_ERROR });
            }
            dirs
        }
    };
    let _ = LOGGER.set(Logger { directives, ansi });
}

fn logger() -> &'static Logger {
    LOGGER.get().expect("logger not initialized")
}

fn level_enabled(level: u8, target: &str) -> bool {
    let log = match LOGGER.get() {
        Some(l) => l,
        None => return level <= LV_INFO,
    };
    let mut best: Option<&Directive> = None;
    let mut best_len: i64 = -1;
    for d in &log.directives {
        if let Some(t) = &d.target {
            if target == t || target.starts_with(t.as_str()) {
                let len = t.len() as i64;
                if len > best_len || (len == best_len && best.map(|b| d.level > b.level).unwrap_or(false)) {
                    best = Some(d);
                    best_len = len;
                }
            }
        }
    }
    if let Some(d) = best {
        return level <= d.level;
    }
    // Global directives.
    let mut result: Option<u8> = None;
    for d in &log.directives {
        if d.target.is_none() {
            result = Some(d.level);
        }
    }
    match result {
        Some(l) => level <= l,
        None => false,
    }
}

#[derive(Clone, Debug)]
struct Span {
    name: String,
    fields: Vec<(String, String)>,
}

impl Span {
    fn new(name: &str, fields: Vec<(String, String)>, span_target: &str) -> Option<Span> {
