# 2 raw server protocol
def raw_server(args, actions, label):
    srv=Proc("server2", ["server"]+args); time.sleep(0.4)
    outputs=[]
    conns=[]
    try:
        for act in actions:
            kind=act[0]
            if kind=="send_recv":
                s=socket.create_connection(("127.0.0.1",7835),timeout=2); s.settimeout(2); conns.append(s)
                s.sendall(act[1])
                try: outputs.append(s.recv(4096))
                except Exception as e: outputs.append(f"ERR {e}".encode())
            elif kind=="sleep": time.sleep(act[1])
    finally:
        for s in conns:
            try:s.close()
            except:pass
        log=srv.stop()
    show(label+" outputs", b"|".join(outputs)); show(label+" log",log)

