# client initial errors via fake server
def fake_client(responses, label, client_args=[]):
    srv_sock=socket.socket(); srv_sock.setsockopt(socket.SOL_SOCKET,socket.SO_REUSEADDR,1); srv_sock.bind(("127.0.0.1",7835)); srv_sock.listen(5)
    cli=Proc("clientf",["local","18080","--to","127.0.0.1"]+client_args); srv_sock.settimeout(3)
    received=[]
    try:
        c,_=srv_sock.accept(); c.settimeout(2)
        for r in responses:
            if r=="RECV":
                try: received.append(c.recv(4096))
                except Exception as e: received.append(str(e).encode())
            elif r=="CLOSE": c.close()
            else: c.sendall(r)
        rc=cli.wait_exit(4); 
        if rc is None: received.append(b"STILL RUNNING")
    except Exception as e: received.append(f"EXC {e}".encode()); rc=cli.poll()
    finally:
        log=cli.stop() if cli.poll() is None or True else ""
        try:c.close()
        except:pass
        srv_sock.close()
    show(label+" received",b"|".join(received)); show(label+f" rc={rc} log",log)

